/* BEGIN museum-analysis-evidence-a.js */
/* First 16 case-specific causal explanations, distinct from end-of-reading reflection questions. */
(function(){const cases={
  "rene-descartes": [
    "Descartes had prepared The World, but news of Galileo’s condemnation made the public presentation of heliocentric cosmology newly consequential. His correspondence records his decision not to publish it at that time. The relevant restraint was therefore not an inability to formulate the scientific claim, but the conflict between publication and the religious authorities whose judgment could affect its reception. His continued writing and later publications show that he withheld a particular work rather than abandoning inquiry altogether.",
    "笛卡尔已经准备好《世界》，但伽利略受审后，以日心说为基础的论述面临更明确的宗教审查风险。他在通信中提到暂停出版。真正发生的是特定著作的公开发行被推迟，而不是数学家不再思考或完全停止研究。"
  ],
  "baruch-spinoza": [
    "The Theological-Political Treatise appeared without its author’s name and with a deliberately misleading imprint. Its criticism of scriptural authority and defence of freedom of philosophical inquiry could expose both the writer and the printing network to religious and civil pressure. Concealing the publishing location and authorship reduced immediate exposure while allowing the argument to circulate. This was a decision about how to publish dangerous ideas, not a decision to remain silent about them.",
    "《神学政治论》使用匿名方式和不真实的出版信息，主要涉及当时宗教与政治权威对相关论述的限制。隐藏作者和印刷来源，使思想能够传播，同时减少作者与出版者被直接识别的风险。因此，他隐去的是身份和出版地点，而不是书中的观点。"
  ],
  "benjamin-franklin": [
    "Franklin's Silence Dogood letters were printed under an invented female identity while he was a young apprentice working in his brother's newspaper. His later autobiography describes slipping material under the printing-house door and concealing authorship. The disguise allowed the writing to be assessed independently of his age and subordinate place in the workshop. It also circumvented the ordinary hierarchy between apprentice and publisher. The surviving evidence supports a publishing tactic within a family business, not a claim that Franklin was permanently unable to speak.",
    "富兰克林年轻时在兄长的印刷所当学徒，以虚构的女性身份发表文章。后来自传记述他把稿件放在印刷所门下，隐瞒作者身份。这种做法使文章不必首先接受兄长对年轻学徒的评价，也绕过了当时的工作等级关系。他隐藏的是写作者身份，以便让文章获得刊登机会。"
  ],
  "thomas-paine": [
    "Common Sense was first published anonymously in 1776, when its case for independence was politically incendiary. Anonymity made it possible for the argument to circulate without requiring readers to receive it under Paine's personal name. The immediate circumstances included the risks of radical political publishing and the convention of unnamed pamphlet authorship. It is inaccurate to claim that Paine did not speak: the pamphlet was publicly distributed. What he initially withheld was attribution of authorship.",
    "《常识》在1776年最初以匿名方式出版，内容直接主张北美殖民地独立。在政治冲突日益激烈的背景下，不署名能够降低个人被立即识别的风险，也符合当时部分政治小册子的出版惯例。潘恩并没有隐去政治观点，而是暂时隐去了作者身份。"
  ],
  "frances-burney": [
    "Burney's first novel Evelina circulated without her public authorial identity. Archival discussion of the manuscript and disguised handwriting indicates that withholding identification involved practical steps, not merely an unrecorded feeling of embarrassment. A young woman entering the literary marketplace faced family expectations and judgments about respectable female authorship. Concealing the name allowed the work to be read before the author's identity became the subject of discussion. It does not prove that every relative opposed her writing.",
    "伯尼出版《伊芙琳娜》时没有公开作者身份，相关手稿材料还显示她采取过掩饰笔迹的措施。这与十八世纪女性从事小说创作时面临的家庭期待和社会评价有关。匿名使作品能够先进入阅读市场，而不是让年轻女性作者的身份成为讨论中心。但现存材料不能证明所有家人都反对她写作。"
  ],
  "ludwig-van-beethoven": [
    "The Heiligenstadt Testament was addressed to Beethoven's brothers and described his worsening hearing and the isolation it caused. It remained among his papers rather than becoming a delivered family letter. The manuscript itself establishes emotional distress and the circumstances he wished to explain. No surviving statement identifies a single final decision not to deliver it. An analysis can link the document to concealment of deafness, shame and strained communication, but it cannot legitimately turn those pressures into a fictional scene of Beethoven choosing silence.",
    "贝多芬在海利根施塔特遗书中向兄弟说明听力恶化及其造成的孤立，文稿最终保留在私人文件中。文本直接表明他承受的困扰，也涉及当时向他人公开听力问题的困难。但没有一份记录能确认他为什么最后没有交付这份文字，因此不能把羞耻、疾病或恐惧中的任何一项写成唯一原因。"
  ],
  "elizabeth-inchbald": [
    "Inchbald destroyed an autobiographical manuscript late in life. Later biographical testimony connects the decision with concern for the feelings or reputations of living people mentioned in the work. Her long career as an actress, dramatist and novelist gave her public experience, so the destruction cannot be explained by a simple fear of publishing as a woman. It concerned a particular autobiographical record and the claims other people might have on their representation within it. Because the manuscript no longer survives, its full contents and the relative weight of motives remain uncertain.",
    "英奇博尔德晚年销毁自传手稿。后来的传记材料提到，她顾虑作品中涉及的在世人物会受到影响。她已经有公开写作和演出的经历，销毁不能简单归因为女性不敢出版，而是与自传会暴露哪些私人关系有关。由于原稿已不存在，无法核实全部内容，也难以确定各项顾虑的重要程度。"
  ],
  "george-sand": [
    "Aurore Dupin published under the name George Sand in a literary economy that assigned different expectations to male and female writers. A masculine pen name helped create a recognisable authorial identity and reduced the pressure of judging a novel solely through its author's gender. The change did not erase the person behind the publications, and her later public career was extensive. Here the withheld information was part of the author's name and social identity at publication, not the substance of her writing.",
    "奥萝尔·迪潘以乔治·桑的名字出版作品，当时文学市场对男女作者有不同期待。男性化笔名使作品能够以新的作者身份进入阅读市场，降低女性身份对作品接受方式的直接影响。她后来仍然积极参与公共文学生活，所以不能把使用笔名解释为一生不敢公开表达。"
  ],
  "elizabeth-gaskell": [
    "Mary Barton first appeared anonymously in a period when unnamed novels were common and women writers could face particular scrutiny. Gaskell's book addressed industrial Manchester and working-class distress, subjects that might invite arguments about both politics and domestic respectability. Anonymity separated the immediate reception of the novel from a public judgment of its author and her family. Published evidence does not identify one exclusive personal fear; the practice should be understood within the conventions and social pressures of Victorian publishing.",
    "盖斯凯尔的《玛丽·巴顿》初版没有署名。维多利亚时代匿名小说并不少见，而一位女性以小说讨论曼彻斯特工业社会与工人处境，可能同时面对文学和家庭声誉的评价。匿名让作品先受到阅读与讨论，作者本人则暂时不进入公众判断。现存材料不足以把这个决定归结为一种单独的恐惧。"
  ],
  "nikolai-gogol": [
    "Gogol destroyed material associated with a later volume of Dead Souls during his final period of religious and artistic turmoil. Accounts by contemporaries and biographers associate the event with his increasingly severe views about the moral purpose of literature and the value of his own unfinished work. The act removed pages from future readers, but the exact contents of the destroyed version are no longer recoverable. It is consequently more accurate to discuss an unstable relationship between religious conviction, authorship and self-judgment than to assert a single command or motive.",
    "果戈里在生命晚期销毁与《死魂灵》后续部分有关的稿件。传记材料将此事与他越来越严苛的宗教追求、对作品道德意义的要求及对写作成果的不满联系起来。原稿已经不能完整复原，因此不能确定哪一个因素最终促成毁稿，也不能把复杂的创作危机写成一条单一命令。"
  ],
  "lewis-carroll": [
    "Charles Lutwidge Dodgson used Lewis Carroll for imaginative literature while continuing to publish mathematical and academic work under his own name. The separation reflected different professional settings and readerships. Archival evidence establishes the deliberate use of two signatures, allowing him to keep his Oxford and literary identities distinct. Nothing in that division requires the assumption that he was afraid to be a writer or secretly detested mathematics. The silence consisted of a managed connection between two public identities.",
    "道奇森以刘易斯·卡罗尔的名字发表文学作品，同时继续以本名从事数学与学术写作。两个名字分别面向不同读者和职业环境，使文学与牛津大学的学者身份保持距离。这是一种可从出版记录确认的身份管理，不等于他不敢承认自己写作，也不能据此推断他讨厌原来的职业。"
  ],
  "florence-nightingale": [
    "Nightingale wrote Cassandra within a broader discussion of women's frustrated education and domestic expectations, but the text circulated in limited publication settings before receiving wider readership much later. The form of distribution belonged to her position within religious, medical and reform networks, where private printing and selective circulation could carry argument to particular audiences. The record does not establish a simple refusal to speak publicly: she wrote extensively on policy and nursing. It establishes the distinct publication history of this one essay.",
    "南丁格尔写《卡珊德拉》时关注女性教育与家庭责任造成的限制，文本起初只在有限范围内流通。她同时通过护理改革、政策写作和私人印刷品积极参与公共事务，因此不能把小范围发行解释为她完全不敢谈女性问题。较明确的事实是这篇文章在不同时期经历了不同范围的传播。"
  ],
  "gerard-manley-hopkins": [
    "Hopkins's decision to destroy early poems was linked by later evidence to his entrance into Jesuit religious life and concern that poetry might distract from that vocation. The act reflected a concrete change in the organisation of his life: obedience, religious formation and the duties he anticipated as a priest. He later resumed writing poetry, demonstrating that the destruction was not an enduring rejection of artistic expression. The source record supports tension between vocation and composition, while details about every destroyed poem are unavailable.",
    "霍普金斯早期烧毁诗稿，与他进入耶稣会、担忧诗歌影响宗教使命有关。当时修会训练与服从要求改变了他的生活安排。此后他重新创作诗歌，说明毁稿不等于永久否定写作。现存资料能说明宗教使命与诗歌活动之间的矛盾，却无法复原被烧掉的作品。"
  ],
  "vernon-lee": [
    "Violet Paget adopted the name Vernon Lee for a public literary career. Historical discussion of her correspondence links the choice with expectations about women's intellectual authority and the reception of critical writing. The pseudonym placed a different identity at the threshold of a reader's encounter with the work. Her essays and books were not suppressed; indeed, she published extensively. The decision therefore concerns authorship and attribution rather than an absence of speech. Its significance lies in which identities were more readily accepted as authoritative.",
    "维奥莱特·佩吉特以弗农·李作为公开笔名，相关通信与研究将此选择联系到当时对女性评论家学术权威的评价。她并非不发表作品，而是选择让作品先以另一种名字获得阅读。笔名遮蔽的是作者的部分身份，而不是思想本身；她后来持续发表大量文学与评论作品。"
  ],
  "katharine-bradley": [
    "Katharine Bradley and Edith Cooper jointly used the name Michael Field for their poems and plays. The shared male signature created a single authorial figure for work produced by two women, and their correspondence shows the identity was maintained deliberately. It could help shape reception in a literary world that often categorised women authors differently. Yet the work also expressed an artistic partnership rather than merely a defensive disguise. The name withheld the full arrangement of authorship from some readers while allowing a collaborative body of work to circulate.",
    "凯瑟琳·布拉德利与伊迪丝·库珀共同使用迈克尔·菲尔德这一笔名发表诗歌和戏剧。男性化的单一署名使读者先看到一个作者形象，真实创作关系则不一定立即被了解。这个名字既可能影响作品在文学市场中的接受，也表达了两位作者主动经营的合作身份，不能只解释成害怕暴露性别。"
  ]
};for(const [id,v] of Object.entries(cases)){const d=window.MUSEUM_HISTORY_LONGFORM?.[id],zh=window.MUSEUM_HISTORY_ZH?.[id];if(!d||!zh)continue;d.analysis[2]=["What constrained the decision",v[0]];d.moment={...(d.moment||{}),why:v[0]};zh.cause=v[1];}})();
;
/* END museum-analysis-evidence-a.js */

/* BEGIN museum-analysis-evidence-b.js */
/* Case-specific causal explanations for remaining 18 new personal dossiers. */
(function(){const cases={
  "edith-cooper": [
    "Edith Cooper and Katharine Bradley deliberately published as the single author Michael Field. The male name permitted an artistic partnership to appear under one public identity in a literary field that treated gender as a marker of authority. Cooper was not an unnamed assistant; she was a joint author whose work entered publication. The change concerned the attribution of collaborative work, not an inability to express its contents.",
    "伊迪丝·库珀与凯瑟琳·布拉德利共同以迈克尔·菲尔德署名出版。女性共同创作被一个男性化的作者名字呈现，既有当时文学界的性别评价背景，也反映她们主动经营的合作方式。库珀不是没有发声的助手，隐去的只是公开署名与真实合作关系之间的一部分信息。"
  ],
  "mark-twain": [
    "Twain arranged for parts of his autobiography to be published after his death. His statements link delay to the freedom to discuss living acquaintances and public institutions without the immediate consequences of publication. The archival history is complicated by dictation, typing, editorial changes and several publication plans. The essential mechanism was timing: postponing a text's audience could widen the author's freedom to name people, but it did not create one final, perfectly sealed manuscript.",
    "马克·吐温安排部分自传材料在身后发表，他曾把延后出版与更自由地评论在世者和公共机构联系起来。其手稿、口述记录与编辑计划经历多次变化，不能简化成一份百年不准公开的完整遗嘱。这里受到控制的是发表时间，以减少文字与现实人物立即发生冲突的后果。"
  ],
  "em-forster": [
    "Forster completed and revised Maurice while homosexual acts between men were criminalised in Britain and the novel described a same-sex relationship with a hopeful ending. Publishing it openly during his lifetime could reveal personal associations and subject the work to legal and social hostility. He nevertheless shared drafts with trusted readers and continued to revise the novel. This was selective circulation, not absolute silence: the work existed and was read privately, but its public release was deferred until after his death.",
    "福斯特写成并修改《莫瑞斯》时，英国法律仍将男性同性性行为刑事化。小说以较为积极的方式描写同性关系，公开发表可能带来法律和社会上的后果。他曾让可信赖的人阅读手稿，说明作品并非完全无人知晓；限制发生在私人传阅与公开出版之间。"
  ],
  "cecilia-payne": [
    "Payne's 1925 doctoral research indicated that stars contain overwhelming amounts of hydrogen and helium, but its public conclusions were made more cautious after advice from the influential astronomer Henry Norris Russell. The power difference involved a young researcher defending a radical interpretation against an established authority within her field. She did not discard the calculations: they remained part of the thesis. The restraint lay in how firmly she was willing to state the implications in a scientific community that had not accepted them.",
    "佩恩1925年的研究数据指向恒星主要由氢和氦组成，但在亨利·诺里斯·罗素等权威的影响下，论文对结果采用了较谨慎的表述。她没有删除计算，也没有放弃天文学研究；受限制的是对结论的确定程度。年轻研究者与学科权威的地位差异，影响了新观点能够以多大把握公开提出。"
  ],
  "mikhail-bulgakov": [
    "Bulgakov destroyed an early manuscript of The Master and Margarita amid state censorship, difficulties obtaining performances and the wider suppression of his work. The burning is documented, and he later returned to the material rather than permanently abandoning it. Political pressure formed a concrete condition around the act, but surviving sources do not record every thought that preceded the destruction. The result was a lost draft followed by renewed writing, not the complete disappearance of the work.",
    "布尔加科夫烧毁《大师与玛格丽特》早期稿件时，作品出版与舞台演出长期受到苏联审查限制。他后来重新写作，说明毁稿并不等于永久放弃作品。政治压力是能够确认的背景，但无法凭毁稿这一行为还原所有心理原因。"
  ],
  "george-orwell": [
    "Eric Blair chose George Orwell as a literary pseudonym when publishing Down and Out in Paris and London. Biographical accounts connect the decision to separating a writing career from his family's reputation and from earlier personal identity. The text itself was not withheld: it entered public circulation. The decision managed recognition and professional identity while the author was writing about poverty and precarious work. It should not be described as an attempt to suppress the experience he reported.",
    "埃里克·布莱尔以乔治·奥威尔的名字出版《巴黎伦敦落魄记》，与避免家庭声誉受到牵连、建立独立的作家身份有关。贫困与流浪生活的内容并没有被隐藏，真正暂时隐去的是作者的本名及其私人关系。使用笔名是一种发表方式，而不是停止写作。"
  ],
  "willa-cather": [
    "Cather specified restrictions on the publication and quotation of her private letters, and the arrangements were enforced by her literary estate for decades. The documented cause is the legal effort to preserve control over personal correspondence after death, not evidence that every letter contained scandal or one hidden secret. The restriction shaped what editors could publish and what researchers could access. It demonstrates a deliberate boundary between literary works released publicly and a private archive managed by heirs.",
    "凯瑟明确要求限制私人信件的引用与发表，遗产管理者在此后多年执行相关要求。这能证明她有意识地控制私人通信的公开范围，却不能据此断定所有信件都隐藏丑闻。受限制的是研究者和编辑能够使用的私人资料，与她已公开发表的文学作品不同。"
  ],
  "barbara-mcclintock": [
    "McClintock's interpretation of genetic transposition met scepticism because it challenged prevailing accounts of stable genes and was developed through demanding maize cytogenetics. She continued research and did not permanently cease communicating results. The relevant conditions were scientific standards of proof, the limited number of colleagues able to evaluate her specialised material, and the difficulty of presenting unfamiliar mechanisms within an established discipline. Later recognition did not transform her earlier career into a simple story of a silenced scientist.",
    "麦克林托克的转座基因研究与当时较稳定的基因观念存在冲突，证据又来自需要专业知识才能判断的玉米细胞遗传学研究。她没有永久停止研究或发表，真正的困难在于新机制如何获得同行理解与认可。把她写成完全沉默的科学家并不准确。"
  ],
  "patricia-highsmith": [
    "Highsmith published The Price of Salt under the pseudonym Clare Morgan in 1952. Its lesbian love story appeared in a literary market where same-sex relationships faced strong social stigma and assumptions about what readers would accept. The pseudonym allowed the book to be distributed without immediately associating it with her established authorial identity. The novel itself was not withheld; it circulated and gained readers. The choice concerned the public connection between the subject matter and its author.",
    "海史密斯1952年以克莱尔·摩根的名字出版《盐的代价》。小说描写女性之间的爱情，当时相关题材面临强烈的社会偏见。笔名使作品能够发表，同时暂时避免与作者既有的公开身份联系起来。被隐藏的是作者身份，而不是小说内容。"
  ],
  "cs-lewis": [
    "A Grief Observed appeared in 1961 under the name N. W. Clerk. It described Lewis's response to the death of his wife and explored anger, confusion and the limits of religious certainty. The alternate signature separated a vulnerable private account from the widely known Christian author who had already become a public figure. Its later editions carried his real name. The timing and title-page evidence show a boundary around personal exposure that changed after publication.",
    "《卿卿如晤》于1961年最初以N. W. 克拉克署名出版，记录路易斯丧妻后的困惑、悲痛和宗教疑问。当时他已有广泛的公众声誉，匿名使私人经验暂时与知名作家身份分开。之后的版本改用本名，说明这种隐匿不是永久性的。"
  ],
  "jd-salinger": [
    "After 1965 Salinger stopped publishing new fiction while maintaining a markedly private life. His reluctance to participate in publicity is documented, but the quantity and contents of writing produced privately remain contested. Public absence from the book market is therefore the established fact; it does not establish that every unpublished work was suppressed by fear or that the author ceased creating. Control over publication and access to his personal life became part of his relationship with readers.",
    "塞林格在1965年后不再公开发表新的小说，同时减少与公众和媒体的接触。私人生活的保护可以从相关材料中观察到，但此后究竟写了多少、为何没有发表每一份作品，仍缺少完整证据。能够确认的是公开出版停止，而不是他必然停止了创作。"
  ],
  "anais-nin": [
    "Nin's diaries appeared first in edited versions that omitted material concerning living people and aspects of the author's relationships. Later unexpurgated editions exposed passages excluded from the original public series. The documented changes reflect editorial choices and a desire to shape the conditions under which private life was made public. The diary was neither simply secret nor fully disclosed: readers at different times encountered substantially different versions of a text written over many years.",
    "阿娜伊丝·宁的日记最初以删节版出版，涉及在世人物和私人关系的部分内容没有公开。后来发行的未删节版本收录了更多文字，说明不同年代的读者读到的并非同一范围的生活记录。这里的限制发生在私人日记进入公开出版的编辑过程中。"
  ],
  "alice-bradley-sheldon": [
    "Alice Bradley Sheldon published science fiction as James Tiptree Jr. and maintained a male-seeming authorial persona in letters with publishers and fellow writers. The disguise affected how her work and correspondence were received in a field where assumptions about gender were influential. The name enabled a distinctive literary identity, not an inability to write. When her identity became known in the 1970s, readers reassessed their earlier assumptions. Her reasons cannot be reduced to a single wish to trick colleagues.",
    "艾丽丝·布拉德利·谢尔登以詹姆斯·蒂普特里二世署名发表科幻小说，并在通信中维持男性化的作者形象。这影响了同业对作品与作者的理解，也使她获得与本名不同的文学身份。七十年代身份公开后，许多人的判断发生改变。不能只把笔名解释成恶意欺骗。"
  ],
  "se-hinton": [
    "The Outsiders was published under S. E. Hinton rather than the author's fully gendered given name. The initials were encouraged by publishing decisions concerned that boys might avoid a novel they knew had been written by a girl. The practice addressed anticipated reader prejudice in the young-adult book market. Hinton did not conceal the existence of the book or refrain from writing; her publisher adjusted the presentation of the author to shape how the work would first be judged.",
    "《局外人》以S. E. 辛顿署名出版，而非完整名字，与出版方担心男性读者因作者是女孩而拒绝阅读有关。首字母降低了作者性别在封面上的可见程度，但小说本身得以广泛出版。这里改变的是读者最初看到的作者身份，而不是小说表达的内容。"
  ],
  "romain-gary": [
    "Romain Gary wrote under the name Émile Ajar and enlisted his relative Paul Pavlowitch to help sustain the apparent separation between the two authorial identities. Gary had already become a celebrated novelist, and the new signature allowed his later writing to reach critics without being read entirely through his existing reputation. It was a complex literary experiment in recognition and reputation, not a case of a powerless writer forced into silence. The later revelation changed how the publications were attributed.",
    "罗曼·加里以埃米尔·阿雅尔署名，并让亲属保罗·帕夫洛维奇参与维持这一作者身份。已经成名的加里希望新作品不完全受旧有文学声誉影响。这个案例主要涉及出版评价与作者身份的安排，而不是一位毫无权力的作者被迫沉默。"
  ],
  "vladimir-nabokov": [
    "Nabokov left an incomplete manuscript of The Original of Laura and instructed that it be destroyed. His heirs ultimately chose preservation and publication. The central withheld act was therefore planned nonpublication by the author, followed by a decision by surviving relatives not to carry out his instruction. The manuscript's unfinished state and the conflict between authorial intent and archival preservation explain why release was delayed. Its later appearance cannot be described as fulfilment of the author's wish.",
    "纳博科夫留下未完成的《劳拉的原型》手稿，并要求将其销毁。继承人后来选择保存并出版，形成作者意愿与遗产保管责任之间的冲突。延期出版与手稿未完成、遗嘱指示及家属决定有关，最终公开也不等于完成作者本人的愿望。"
  ],
  "elena-ferrante": [
    "Ferrante deliberately keeps a separation between the books released under her pen name and the private individual behind it. In interviews she has explained that books should travel independently of the author's public persona and that the media's demand for biography can constrain reading. This is an expressly articulated publishing philosophy, not silence about literature. Her refusal concerns the personal identity and publicity apparatus attached to authorship. Speculation about who she is does not strengthen the explanation.",
    "费兰特在访谈中说明，她希望作品能够独立于作者私人形象传播，并拒绝媒体对个人经历的过度关注。她没有停止文学表达，而是限制外界取得作者私生活和身份信息的渠道。这是一种主动提出的出版立场，不需要借猜测她的真实身份才能解释。"
  ],
  "jk-rowling": [
    "Rowling published The Cuckoo's Calling as Robert Galbraith after years of extraordinary fame under her own name. Her own public explanation emphasised the freedom to be read as an unknown writer and to obtain reactions unshaped by an established reputation. The pseudonym initially separated the new crime novel from her celebrity status; once the identity became public, reception changed. The choice was a controlled experiment in authorial recognition, not an example of oppression that silenced the writer.",
    "罗琳以罗伯特·加尔布雷思署名出版《布谷鸟的呼唤》，她本人解释过希望以不知名作者的身份获得读者反应，不受既有名气左右。笔名暂时切断了新侦探小说与公众熟悉的作者身份的联系。这属于主动调整出版身份，而非因社会压迫而无法说话。"
  ]
};for(const [id,v] of Object.entries(cases)){const d=window.MUSEUM_HISTORY_LONGFORM?.[id],zh=window.MUSEUM_HISTORY_ZH?.[id];if(!d||!zh)continue;d.analysis[2]=["The documented obstacle or purpose",v[0]];d.moment={...(d.moment||{}),why:v[0]};zh.cause=v[1];}})();
;
/* END museum-analysis-evidence-b.js */

/* BEGIN museum-analysis-legacy-a.js */
/* Evidence-grounded interpretive answers for personal archives, distinguishing imposed coercion from actual resistance. */
(function(){const cases={
  "anne-frank": [
    "Anne Frank's family's concealment followed concrete occupation measures: Jews lost rights, faced arrests and deportation, and had to avoid exposing the people sheltering them. The diary was not a refusal to write. Anne recorded life in the annex and later revised parts of it after hearing an appeal for wartime testimony. The restriction was on public visibility and movement, enforced by Nazi persecution and the danger of discovery. Her death and the diary's later publication must not be interpreted as a voluntary decision to remain silent.",
    "安妮·弗兰克一家隐藏身份，是因为纳粹占领当局实施反犹政策与驱逐，公开行踪会危及所有藏身者以及帮助他们的人。日记仍在持续书写，安妮后来还根据战时见证记录的号召修订过文字。被限制的是她在外界公开生活和安全发声的条件，不是她自愿不记录自己的经历。"
  ],
  "white-rose": [
    "The White Rose students actually did resist. They produced and distributed leaflets despite a Nazi state apparatus able to arrest, prosecute and execute dissenters. Their secrecy protected the circulation of messages and the identities of those involved. It cannot be described as their failure to speak. The important causal distinction is between clandestine publication under dictatorship and the many people who could not safely participate in such work. The group's eventual arrests followed active opposition, not passive silence.",
    "白玫瑰成员确实通过印制和散发传单反抗纳粹统治。他们隐瞒身份和传递方式，是因为公开反对可能招致逮捕与处决。保密是为了让已经采取的行动能够继续，并非他们没有勇气发声。这个档案不能被解释为沉默者的故事。"
  ],
  "rosa-parks": [
    "Rosa Parks's refusal to surrender her bus seat was a public act against segregation, not a failure to challenge it. Her decision took place within Montgomery's legal rules, the long organisation of the local Black community and previous challenges to bus discrimination. The significance of the incident depended on the arrest, legal case and organised boycott that followed. Any analysis of pressure must distinguish the coercive system passengers faced from Parks's documented choice to defy it. She was not silenced into compliance.",
    "罗莎·帕克斯拒绝在公车上让座，是公开反对种族隔离的行动，不是没有反抗。此事处于蒙哥马利长期歧视与黑人社区组织活动的背景之中，后续逮捕、法律争议及联合抵制公交车也影响了历史结果。需要分析的是制度如何限制乘客，以及她如何实际拒绝，而不是假装她选择了沉默。"
  ],
  "anna-akhmatova": [
    "Akhmatova composed Requiem under Soviet repression while people close to her were imprisoned. Preserving its lines on paper could create danger during searches, so poems were sometimes memorised by trusted listeners instead of retained as manuscripts. This was a strategy for survival of the work under surveillance, not an absence of artistic speech. The specific mechanism was the danger that written evidence could expose the author and listeners. Later publication became possible under changed political conditions.",
    "阿赫玛托娃在苏联政治镇压时期创作《安魂曲》，亲近之人曾遭拘捕。文字手稿在搜查中可能成为危险证据，因此部分诗句由可信赖的听众背诵保存。她没有停止写作，受到限制的是作品能够以文字形式安全保存和公开传播的条件。"
  ],
  "nicolaus-copernicus": [
    "Copernicus circulated elements of his heliocentric model among learned contacts before De revolutionibus appeared near the end of his life. The gap between private discussion and publication involved scholarly criticism, the time required to prepare a technical treatise and concern over reception. Historical sources do not establish religious fear as the one decisive cause; his situation preceded Galileo's later trial. What he withheld for years was a complete printed defence, not all discussion of his astronomical system.",
    "哥白尼在《天体运行论》公开出版前，已经在学者之间传播日心说的部分内容。完整著作的出版涉及技术论证、对同行批评的顾虑和准备时间，不能将推迟出版完全归因于害怕宗教审判，更不能把之后伽利略的经历直接套用到他身上。被延后的是完整的印刷出版，而不是所有学术交流。"
  ],
  "harriet-jacobs": [
    "Harriet Jacobs concealed her whereabouts because slavery allowed the people claiming ownership over her to pursue and seize her. The small attic space in which she hid restricted movement, health and contact with her children while offering some protection against recapture. Her concealment was a direct response to physical and legal danger. She later published a narrative exposing sexual coercion and the separation of families under slavery. The source is therefore about protective secrecy under persecution, not quiet acceptance of enslavement.",
    "哈丽雅特·雅各布斯躲藏，是因为奴隶制度允许声称占有她的人追捕并将她带回。狭小的藏身空间长期限制了她的活动和与孩子相处的机会，却减少了被抓获的危险。她后来公开出版有关奴隶制度的自述，所以隐匿行踪并非认同奴役，而是面对法律与暴力威胁的保护行动。"
  ],
  "emily-dickinson": [
    "Dickinson circulated poems to selected correspondents and preserved many others in handwritten fascicles rather than publishing them in the newspapers or books available during her lifetime. No definitive personal testimony explains every decision about submission and publication. She cared about form, copying, intended readers and versions of poems; editors of the period could alter punctuation or wording. The outcome was selective readership and a large body of private manuscripts, not proof of a single fear of rejection or universal opposition to print.",
    "狄金森向特定朋友与通信对象传阅诗歌，也将大量作品保存在自己编订的手稿中。没有明确的个人证词能解释每一次不投稿的原因。她对诗歌形式、抄写、收信人和文字版本有持续安排，而当时编辑可能修改标点与表达。能够确认的是选择性传播与私人保存，不是单一的害怕被拒绝。"
  ],
  "alan-turing": [
    "Turing faced different restrictions in different spheres. Wartime cryptographic work was governed by military secrecy, preventing public discussion of achievements even when the work was highly valued. Later, British criminal law punished sexual relations between men and subjected Turing to prosecution. Those were separate mechanisms of enforced concealment and punishment. He was not uniformly silent about his private identity. The case requires analysis of state security and criminal law rather than a generic claim that a gifted person simply lacked courage.",
    "图灵战时的密码破译工作受到军事保密规定限制，即使研究成果十分重要，也不能公开说明细节。战后英国刑法仍惩罚男性同性性行为，使其私人生活受到法律追究。这是军事机密与刑事法律两种不同的制度约束，不能简单说图灵一生不敢表达自己的身份。"
  ],
  "claudette-colvin": [
    "Claudette Colvin refused segregation on a Montgomery bus before the more widely commemorated arrest of Rosa Parks. Her act was documented and contributed to the wider legal history of bus segregation, including Browder v. Gayle. Differences in organisational decisions, public messaging and later remembrance affected which individuals became symbols of the movement. That uneven recognition is not evidence that Colvin failed to resist. The question for analysis is how historical visibility is produced after an act has already occurred.",
    "克劳黛特·科尔文早于罗莎·帕克斯在蒙哥马利公车上拒绝服从种族隔离安排。她的行动进入法律与民权运动史，后来也与相关诉讼相联系。不同组织的宣传选择和历史叙述影响了公众记住谁，但这不意味着科尔文本人没有反抗。"
  ],
  "oscar-wilde": [
    "Wilde published and performed extensively, yet British criminal law and public moral expectations exposed relationships between men to prosecution and scandal. His trials followed public conflict and disclosures rather than a lifelong inability to speak. The restrictive mechanism concerned sexual conduct, private relationships and the reputational consequences of exposure, not literary publication as such. Public fame could coexist with vulnerability under a law that treated aspects of a person's intimate life as criminal.",
    "王尔德长期公开发表作品并参与文学活动，但英国当时的刑法将男性同性性行为纳入惩罚范围，社会舆论也可能造成严重声誉损失。他的审判源于具体的法律与公开冲突，限制的重点在私人关系与性行为，而不是他完全无法发表文学观点。"
  ],
  "janusz-korczak": [
    "Korczak advocated children's dignity and opportunities to participate in decisions within his educational work. Nazi occupation later subjected the children in his care and the staff around them to confinement, deprivation and deportation. His public educational philosophy and the subsequent destruction imposed by the occupying authorities must be separated. The latter was violent coercion by a state apparatus, not a decision by Korczak to withdraw his words. His case documents advocacy followed by persecution rather than voluntary silence.",
    "柯尔恰克长期主张尊重儿童，试图在教育实践中给予孩子参与生活决定的空间。纳粹占领后，他照顾的儿童与工作人员遭受隔离、剥夺和驱逐。前者是主动表达的教育立场，后者是占领当局强加的暴力制度，不能把他后来无法继续工作的处境说成自愿沉默。"
  ],
  "etty-hillesum": [
    "Hillesum kept diaries and letters while anti-Jewish measures increasingly restricted the lives of people in occupied Netherlands. Her writing recorded the changing conditions and her reflections as deportation approached. The eventual interruption in surviving testimony resulted from coercive displacement and her death, not an authorial choice to end the story. Preservation and later editing determined which pages reached readers. The evidence distinguishes the voice she continued to produce from the state violence that prevented further writing.",
    "埃蒂·希勒瑟姆在荷兰遭占领期间继续写日记和书信，记录反犹政策不断加剧的生活限制。后来可保存的文字中断，与强制迁移和死亡有关，而不是作者选择不再讲述。资料能说明她持续写作，也说明暴力制度如何阻断进一步的记录。"
  ],
  "ida-b-wells": [
    "Ida B. Wells investigated and wrote against lynching even after white supremacist threats and the destruction of her newspaper's premises. The violence targeted the circulation of evidence and sought to make such reporting costly. Her departure from Memphis and continued journalism show that exposure to intimidation did not end her public advocacy. The causal account is therefore not why she 'chose silence', but how racial violence attempted to suppress an already outspoken journalist.",
    "艾达·B. 韦尔斯公开调查并报道私刑问题，即使报社受到白人至上主义者的暴力威胁与破坏，她仍继续新闻活动。暴力的目标是阻止证据传播、提高报道成本，而不是她本人已经接受沉默。这个案例应解释制度和暴力如何试图压制一个已经发声的人。"
  ],
  "liu-xiaobo": [
    "Liu Xiaobo published political arguments and participated in public advocacy; his later imprisonment restricted his movement and opportunities to communicate. The relevant silence was imposed through state punishment, not the result of deciding never to express political views. Written statements and prison records document active expression followed by coercive limits. A responsible analysis distinguishes what authorities prohibited from what Liu had already deliberately said.",
    "刘晓波曾公开发表政治观点并参与公共倡议，后来受到国家刑事处罚和监禁，行动与通信范围因而受到限制。这里的沉默来自表达之后的强制惩罚，并不是他没有勇气发表意见。应区分当局禁止的行为与他实际已经表达过的观点。"
  ],
  "galileo-galilei": [
    "Galileo openly published and defended astronomical arguments, then faced proceedings before Catholic authorities that limited how particular claims could be asserted. The restrictions followed a clash over scriptural interpretation, ecclesiastical authority and what counted as a demonstrable scientific proposition. The record includes publication, investigation and compelled changes in public position. It does not support the claim that Galileo never dared to speak; it documents a scholar whose expression was curtailed by an institution with legal power.",
    "伽利略已经公开发表并捍卫天文学观点，后来教会审查限制了某些主张的表达方式。这与经文解释、教会权威和科学证明标准之间的争议有关。史料记载了公开出版、审查与被迫改变表述的过程，而不是一位学者从未敢提出观点。"
  ]
};for(const [id,v] of Object.entries(cases)){const d=window.MUSEUM_HISTORY_LONGFORM?.[id],zh=window.MUSEUM_HISTORY_ZH?.[id];if(!d||!zh)continue;d.analysis[2]=["What actually limited expression",v[0]];d.moment={...(d.moment||{}),why:v[0]};zh.cause=v[1];}})();
;
/* END museum-analysis-legacy-a.js */

/* BEGIN museum-analysis-legacy-b.js */
/* Second evidence-based analysis audit: attribution, selective secrecy, resistance versus enforced censorship. */
(function(){const cases={
  "rosalind-franklin": [
    "Franklin produced X-ray diffraction research on DNA in a scientific environment where data moved through laboratories, personal conversations and competing groups. Her contributions entered the scientific record, although later accounts often placed other scientists at the centre of the discovery. The historical problem is the organisation of collaboration, permission to use data and the distribution of scientific credit. Franklin was not simply a researcher who failed to speak: she published and worked actively. Her uneven recognition is a question of attribution, not evidence that she chose silence.",
    "富兰克林通过X射线衍射研究DNA，研究数据在不同实验室与科研人员之间传递，后来对发现过程的记述又常将其他人置于中心。需要讨论的是数据使用、合作关系及学术功劳如何分配，而不是将她写成因为没有勇气而不发表研究的人。她确实持续工作并发表成果，受到影响的是成果被如何归属和记忆。"
  ],
  "artemisia-gentileschi": [
    "Gentileschi gave testimony in a rape trial in which legal procedures and gendered judgments shaped how her words were examined. The surviving court record demonstrates that she did speak, sometimes under coercive conditions, rather than passively accept events. The legal hierarchy placed a young woman in a different position from male judges and witnesses. Later biographies sometimes allowed the trial to overshadow her substantial artistic career. The interpretive problem is how testimony was evaluated and how an artist's work came to be remembered.",
    "真蒂莱斯基在强奸案审判中作过证，法庭程序与性别规范影响了人们如何评价她的言语。她确实表达过自己的经历，并非一直沉默。年轻女性面对男性主导的司法程序，权力和可信度并不对等。后来的传记又常以审判覆盖她的绘画成就，因此应分析证词的待遇与历史叙述，而不是虚构她没有发声。"
  ],
  "elizabeth-keckley": [
    "Keckley published Behind the Scenes in 1868, drawing on experiences as an formerly enslaved dressmaker and a confidante of Mary Todd Lincoln. The backlash involved racial expectations and notions of privacy surrounding a prominent political household. The constraint was not her failure to publish: the book existed and circulated. Her public testimony challenged assumptions about who could recount intimate events involving socially powerful people, and the consequences of doing so were unequally distributed by status and race.",
    "凯克利1868年出版《幕后》，谈及自己从奴隶身份获得自由、从事裁缝工作，以及与玛丽·托德·林肯交往的经历。作品引起的争议涉及种族等级和名人家庭对隐私的要求。她并没有不敢出版，反而已经公开讲述；问题在于处于不同社会地位的人，是否被同等允许叙述他们共同经历的事情。"
  ],
  "harriet-tubman": [
    "Tubman concealed routes, identities and arrangements because disclosure could expose people escaping slavery to capture. This was operational secrecy within an active campaign of liberation. The legal and physical dangers of the Fugitive Slave Acts and slaveholders' pursuit explained why detailed information had to remain restricted. Her choices should not be interpreted as unwillingness to resist: she repeatedly undertook dangerous journeys to help others escape. Silence concerning logistics helped protect people who depended on her knowledge.",
    "塔布曼隐瞒救援路线、参与者身份和具体行动，是因为公开这些信息会使逃离奴隶制的人遭到追捕。逃奴法及奴隶主的追索权构成现实危险。她多次主动帮助他人逃亡，不能被描述为没有勇气反抗。相关信息的保密，是为了维持已经发生的救援行动。"
  ],
  "mary-berg": [
    "Mary Berg kept a diary during the persecution and confinement of Jews in Warsaw. Her ability to leave Europe and the later preservation of her writing depended on unusual documentary and family circumstances. The Nazi occupation limited movement and made many forms of public speech dangerous, yet her record was not an act of willing silence. Publication was possible because her manuscripts survived and reached an audience abroad; countless other people's accounts were destroyed or never written. The explanation is unequal survival of testimony under persecution.",
    "玛丽·伯格在华沙犹太人受迫害和被隔离期间坚持写日记。她后来能够离开欧洲，文字也被保存并公开，受到家庭处境与特殊历史条件影响。纳粹占领限制人们的行动与表达，日记的幸存并不说明其他人不愿说话，而是个人资料能够保存下来的条件极不平等。"
  ],
  "abraham-lincoln": [
    "Lincoln drafted a sharply critical letter to General George Meade after the Battle of Gettysburg because he believed an opportunity to pursue the retreating Confederate army had been missed. The Library of Congress preserves the draft, which was never signed or delivered. His frustration is directly evident in its wording; the precise reason he withheld it is not stated as one definitive decision. One plausible, historically bounded explanation is that sending the rebuke could have damaged relations with a commander he still needed in the field. The outcome was restraint in military correspondence, not silence about the war.",
    "林肯在葛底斯堡战役之后，认为米德将军错过了追击南方邦联军队的机会，因而起草了一封严厉的批评信。美国国会图书馆保存了未署名、未送达的草稿。信中明确表现出他的失望，但没有记录能直接证明他最终为何不发出。继续维持与前线指挥官的合作，是基于当时军事关系可以提出的解释，不能当作林肯自己确认的唯一动机。"
  ],
  "anne-lister": [
    "Lister recorded her life in extensive diaries, using a special code for portions concerning intimacy and private relationships. The code restricted easy access by contemporaries while allowing her to keep a detailed written record. In a society with strong legal and social expectations concerning women, property and same-sex relationships, selective privacy had practical uses. She was not afraid of all public activity: Lister managed property and travelled. What she withheld was the ready intelligibility of particular diary passages to unintended readers.",
    "安妮·李斯特长期撰写日记，并用特殊密码记录部分亲密关系与私人生活。这样既能保存详细的个人记载，又减少未经允许的读者直接理解某些内容的机会。她同时积极管理财产并旅行，并非完全不参与公共生活。受到限制的是特定日记文字的可读对象，而不是写作本身。"
  ],
  "sophie-germain": [
    "Germain communicated mathematical work under the male name M. LeBlanc while women had limited access to advanced mathematical instruction and networks. The disguise made it easier for the recipient to assess correspondence without immediately filtering it through expectations about a woman's abilities. Her own later communication and achievements demonstrate sustained intellectual activity. The relevant pressure was unequal access to mathematical institutions and the credibility associated with gender, not lack of scientific ambition. Historical portraits attributed to Germain also require separate verification, as authentic likenesses are disputed.",
    "热尔曼曾以勒布朗先生的男性名字进行数学通信，当时女性进入高等数学教育与学术圈子的机会非常有限。使用男性身份能够减少通信一开始受到性别成见影响的可能。她后来持续研究数学，并不是没有学术抱负。约束主要来自学习与交流渠道的不平等，而不是不敢思考数学问题。关于她的历史肖像是否真实，也需要另行核实。"
  ],
  "fanny-mendelssohn": [
    "Fanny Mendelssohn composed extensively but faced a family culture in which public professional musical life was encouraged more for her brother Felix than for her. Her father framed music as a suitable accomplishment for a woman rather than a primary career, and Felix's views could influence her plans for publication. She nonetheless performed, organised musical gatherings and eventually issued works under her own name. The constraint was unequal recognition and encouragement within family and music publishing, not absolute inability to create or appear before others.",
    "范妮·门德尔松创作了大量音乐，却在家庭中面对与弟弟费利克斯不同的职业期待。父亲更倾向把音乐视作女性的修养而非职业，弟弟对出版的看法也会影响她的决定。但她组织音乐聚会、演奏并最终以本名出版作品。限制主要存在于家庭支持和公开职业认可的差异，而不是她从未从事音乐活动。"
  ],
  "eileen-chang": [
    "Eileen Chang's unfinished or withdrawn literary projects were shaped by revision, personal experience and judgments about the work itself. The surviving correspondence documents changes in her attitude toward particular manuscripts and requests concerning their preservation. Those decisions cannot be reduced to one secret shame or a universal refusal to publish. She was an established public writer; withholding or destroying specific versions concerned control of a work's future circulation. The source record distinguishes her documented requests from later editorial interpretations.",
    "张爱玲已有广泛的公开写作经历，部分小说稿件或版本未发行，与修改、对作品质量的判断及个人经历有关。保存下来的通信能够证明她对特定稿件的处理意见发生过变化，但不能把不出版或要求销毁统一解释为某种羞耻或恐惧。重点是作家对特定作品未来流通范围的控制。"
  ],
  "charlotte-bronte": [
    "Charlotte Brontë later stated in her biographical notice that she and her sisters adopted ambiguous pen names partly to avoid prejudiced judgments attached to being female authors. Currer Bell allowed publication under a signature that did not disclose gender immediately. The novels were published, not silently abandoned. Her own statement provides unusually direct evidence of the reason for using a pen name, although it does not establish that every reader or critic was biased in the same way.",
    "夏洛蒂·勃朗特后来明确说明，姐妹们使用不直接表明性别的笔名，部分原因是希望避免读者对女性作者的偏见。柯勒·贝尔这一署名让作品先以作者身份而非性别获得阅读。小说已经公开出版，隐藏的是部分作者身份，不是故事内容。"
  ],
  "emily-bronte": [
    "Emily Brontë published as Ellis Bell within a joint arrangement made by the three sisters. Charlotte's later account gives evidence that gendered prejudice mattered to the shared decision. Emily's own private reasoning is less fully documented, and her circumstances should not be flattened into Charlotte's exact motives. Her poetry and novel reached readers; the withheld element was the immediately identifiable female authorship, not the literary ideas within Wuthering Heights.",
    "艾米莉·勃朗特以埃利斯·贝尔发表作品，署名属于姐妹共同使用笔名的安排。夏洛蒂的后来叙述能说明性别偏见影响了这一决定，但不能把姐姐的每一种想法直接归给艾米莉。她的小说与诗歌都已传播，暂时隐藏的是女性作者身份。"
  ],
  "anne-bronte": [
    "Anne Brontë used Acton Bell as part of the sisters' publishing strategy. Gender-ambiguous names could reduce an early reader's reliance on assumptions about women writers. Charlotte later explained the decision, but Anne's full individual reasoning cannot be reconstructed from that one statement. Her novels appeared in print and addressed difficult social subjects. This was a tactical presentation of authorship rather than a refusal to publish her observations.",
    "安妮·勃朗特以阿克顿·贝尔署名出版，与姐妹共同避免作品先因女性身份受到偏见有关。夏洛蒂留下相关说明，但不能据此完整重建安妮本人的每项顾虑。她公开发表小说并触及社会问题，因此这里属于作者身份的策略性呈现，而不是对写作内容的沉默。"
  ],
  "jane-austen": [
    "Austen's Sense and Sensibility appeared under the phrase 'By a Lady', and later novels initially withheld her personal name from the title page. Anonymous or semi-anonymous publication was an established convention in her period, especially around women's fiction and household respectability. The practice let the work circulate without naming the private person at the outset. No single surviving declaration attributes all her publishing choices to personal fear; the firm evidence is the form of the first editions and the conventions of her literary world.",
    "奥斯汀的《理智与情感》初版署名是“一位女士”，后来几部作品最初也没有在封面公开完整姓名。十八世纪末至十九世纪初，女性小说匿名或半匿名出版并不罕见，与作者私人生活及社会体面观念有关。但没有单一证据能证明奥斯汀所有选择都源于恐惧。可以确认的是首版署名方式和时代出版习惯。"
  ],
  "george-eliot": [
    "Mary Ann Evans chose George Eliot as a publishing name at a time when women's novels were often treated through gendered expectations. She also lived in a relationship that attracted public moral judgment, making separation between literary identity and private biography meaningful. The pseudonym allowed books to appear as the work of George Eliot while Evans continued extensive intellectual activity. Its purpose was authorial positioning, not an inability to state her ideas in fiction or criticism.",
    "玛丽·安·埃文斯以乔治·艾略特署名，既处于女性文学受性别评价影响的时代，也因私人伴侣关系面对社会道德议论。笔名把文学作者与私人传记保持一定距离，使作品能够公开发表。她并非不敢表达思想，而是调整了作品进入公众视野时的作者身份。"
  ],
  "louisa-may-alcott": [
    "Alcott used other signatures for different kinds of popular fiction, including sensational writing she did not always associate publicly with her later family-literature reputation. Publishers, genres and readerships rewarded different authorial identities. The use of pseudonyms could separate commercial experimentation from expectations attached to a recognised name. Her writings still reached readers; the withheld part was attribution or linkage between distinct bodies of work. The relative importance of income, reputation and artistic interest may have varied by publication.",
    "奥尔科特曾为不同类型的小说使用不同笔名，包括与后来家庭文学声誉不同的通俗和刺激性题材。出版市场对不同作品和作者身份有不同期待，笔名可以区分商业写作与既有名声。作品实际已经发表，隐去的是不同类型作品与同一作者之间的联系。"
  ],
  "thomas-more": [
    "Thomas More's refusal to affirm the required oath arose from religious conscience and the legal dangers of explicit disagreement with Henry VIII's royal supremacy. Remaining silent about the precise grounds for refusal could serve a legal purpose because a spoken statement might be used as evidence of treason. He was nevertheless imprisoned and executed; silence offered no complete protection against state power. The historical mechanism was a conflict between conscience, compelled declarations and a legal regime that could punish dissent.",
    "托马斯·莫尔不愿宣誓接受亨利八世要求的宗教与王权立场，与良心信仰和当时的法律后果有关。他对拒绝理由的沉默具有法律上的考虑，因为明确表态可能被用作叛国指控的证据。但他仍被监禁并处决，沉默并未真正使其免受惩罚。这是宗教良心、强制宣誓与国家刑法之间的冲突。"
  ]
};for(const [id,v] of Object.entries(cases)){const d=window.MUSEUM_HISTORY_LONGFORM?.[id],zh=window.MUSEUM_HISTORY_ZH?.[id];if(!d||!zh)continue;d.analysis[2]=["The mechanism and the available evidence",v[0]];d.moment={...(d.moment||{}),why:v[0]};zh.cause=v[1];}})();
;
/* END museum-analysis-legacy-b.js */

/* BEGIN museum-analysis-legacy-c.js */
/* Final three historical cases: political succession and editorial control of personal records. */
(function(){const cases={
  "elizabeth-i": [
    "Elizabeth I repeatedly resisted pressure to identify a successor while unmarried and without children. Naming a particular heir could strengthen that person's political faction, weaken the reigning queen's bargaining position and turn debate over the future into a conflict over present authority. These consequences are grounded in the political circumstances of Tudor succession and diplomatic marriage negotiations. The silence was about a specific state decision with immediate effects, not a general inability to speak. No single surviving confession establishes a private motive sufficient to explain every occasion on which she avoided committing herself.",
    "伊丽莎白一世在没有子女继承王位的情况下，多次拒绝公开确定继承人。指定人选可能使其支持派系立即壮大，也可能削弱在位女王对朝臣及外国势力的政治影响力。这与都铎王朝的继位争议、婚姻外交和宫廷派系有关。她未明确宣布继承人属于特定政治决定，并非一般意义上的无法发声。"
  ],
  "queen-victoria": [
    "Queen Victoria wrote extensively in personal journals, but the surviving record was later shaped by her daughter Princess Beatrice, who copied and edited much of the material after her mother's death and destroyed many originals. Royal privacy, family reputation and the presentation of a reign influenced how diaries were treated as historical documents. Because the editions were produced by another person, the removal of passages cannot automatically be attributed to Victoria's own wish to withhold each specific detail. The central mechanism is posthumous editorial control over a private royal archive.",
    "维多利亚女王长期写日记，但她去世后，女儿比阿特丽斯公主重新抄录、删改了大量内容，部分原稿随后被销毁。王室隐私、家族声誉及统治历史的呈现方式都与这一编辑过程有关。因此，某段记录未能保存下来，不一定是女王本人作出的沉默选择，还涉及后人对档案的管理。"
  ],
  "thomas-hardy": [
    "Thomas Hardy's surviving papers reflect deliberate management of manuscripts, notebooks and personal correspondence, including documents that were destroyed or altered near the end of his life. His relationship with his first wife Emma, the making of his authorised biography and concern for how private events would appear to posterity are relevant to this documentary history. The existence of destroyed materials is recorded, but their complete contents are not recoverable. The strongest explanation is control over personal evidence and future biography, rather than a single proven fear attached to each absent page.",
    "哈代晚年对手稿、笔记及私人信件的保存作出过选择，部分文件遭到销毁或整理。这与他和第一任妻子艾玛的复杂关系、授权传记的撰写，以及私人生活如何被后人记述有关。史料能够证明一些材料被删除或损毁，却无法复原所有内容，因此不能把每一页消失的原因都归结为同一种恐惧。"
  ]
};for(const [id,v] of Object.entries(cases)){const d=window.MUSEUM_HISTORY_LONGFORM?.[id],zh=window.MUSEUM_HISTORY_ZH?.[id];if(!d||!zh)continue;d.analysis[2]=["Specific historical pressure and evidence",v[0]];d.moment={...(d.moment||{}),why:v[0]};zh.cause=v[1];}})();
;
/* END museum-analysis-legacy-c.js */

